37	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
38	// success; on failure prints an error tagged with `ctx` and returns "". The
39	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
40	// missing path fails with a clear "ELF not found" instead of being handed to the
41	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
42	// up-front check run_hybrid already does.
43	std::string abs_elf(const std::string& path, const std::string& ctx) {
44	  std::error_code ec;
45	  fs::path abs = fs::absolute(path, ec);
46	  if (ec) {
47	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
48	                 ctx.c_str(), path.c_str());
49	    return "";
50	  }
51	  if (!fs::is_regular_file(abs, ec)) {
52	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
53	                 path.c_str());
54	    return "";
55	  }
56	  return abs.string();
57	}
