59	// Validate the lone-ELF positional shape the standalone models require: print
60	// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
61	int check_one_elf(const Cli& cli, const char* model) {
62	  if (cli.positional.empty()) {
63	    std::fprintf(stderr,
64	                 "andesim run --mode %s: missing ELF (the workload to run; "
65	                 "e.g. a tests/fixtures/<name>.elf)\n",
66	                 model);
67	    return 2;
68	  }
69	  if (cli.positional.size() > 1) {
70	    std::fprintf(stderr,
71	                 "andesim run --mode %s: unexpected argument '%s' "
72	                 "(engine args go after --)\n",
73	                 model, cli.positional[1].c_str());
74	    return 2;
75	  }
76	  return 0;
77	}
