79	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
80	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
81	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
82	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
83	// reports the plan, it does not run it.
84	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
85	                  const std::vector<std::string>& labels) {
86	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
87	  for (size_t i = 0; i < argvs.size(); ++i) {
88	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
89	                labels[i].c_str());
90	    std::printf("%s\n", render_argv(argvs[i]).c_str());
91	  }
