95	// The standalone spine: take a single ELF, then run the resolved engine
96	// standalone with the post-`--` args appended verbatim (exec_passthrough --
97	// inherit stdio, no timeout, propagate the exit code, so an interactive
98	// gdbstub / monitor / semihosting console works unchanged). The per-model
99	// engine + selection are resolved by the caller; `model` here only labels
100	// the positional diagnostics.
101	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
102	                   const char* model, const std::vector<std::string>& extra = {}) {
103	  if (int rc = check_one_elf(cli, model)) return rc;
104	  // QEMU's -bios flag searches its data directory for relative paths rather
105	  // than the CWD; resolve to absolute so the engine finds the ELF.
106	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
107	  if (elf.empty()) return 2;
108	  // `extra` (framework flags, e.g. fast's -m) precedes the post-`--` args, so a
109	  // user's own flag after `--` wins.
110	  std::vector<std::string> args = extra;
111	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
112	  std::string err;
113	  const std::vector<std::string> argv =
114	      passthrough_argv(eng, "standalone", elf, args, err);
115	  if (!err.empty()) {
116	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
117	    return 2;
118	  }
119	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
120	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
121	  if (cli.dry_run)
122	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
123	  return exec_passthrough(argv);
124	}
