126	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
127	// only the built-in qemu descriptor, so it resolves that directly rather than
128	// discover_engines(), which would spawn a --describe subprocess per Verilator
129	// build only to discard them all here.
130	int run_fast(const Cli& cli) {
131	  // fast is QEMU-only; an explicit engine must name it.
132	  if (!cli.engine.empty() && cli.engine != kQemuId) {
133	    std::fprintf(stderr,
134	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
135	                 cli.engine.c_str());
136	    return 2;
137	  }
138	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
139	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
140	  std::string err;
141	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
142	  if (!err.empty()) {
143	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
144	    return 2;
145	  }
146	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
147	  if (cli.gdb) {
148	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
149	    extra.push_back("-gdb");
150	    extra.push_back("tcp::" + port);
151	    extra.push_back("-S");
152	  }
153	  return run_standalone(cli, builtin_qemu(), "fast", extra);
154	}
