156	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
157	// its --jtag-port only after it has reset and halted the hart, so the debugger we
158	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
159	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
160	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
161	// single debugger slot). Returns false on timeout.
162	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
163	  constexpr int kPollMs = 50;
164	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
165	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
166	      char line[512];
167	      while (std::fgets(line, sizeof line, f)) {
168	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
169	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
170	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
171	        unsigned lport = 0, st = 0;
172	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
173	            && st == 0x0A && lport == port) {
174	          std::fclose(f);
175	          return true;
176	        }
177	      }
178	      std::fclose(f);
179	    }
180	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
181	  }
182	  return false;
183	}
