185	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
186	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
187	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
188	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
189	  const char* iceman = std::getenv("ICEMAN");
190	  if (!iceman || !*iceman) {
191	    std::fprintf(stderr,
192	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
193	                 "(export ICEMAN=<path to ICEman binary>)\n");
194	    return 2;
195	  }
196	  // Build vsim argv from the standalone template, appending user passthrough
197	  // and the JTAG port flag.
198	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
199	  if (elf.empty()) return 2;
200	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
201	  std::vector<std::string> vsim_pass = cli.passthrough;
202	  vsim_pass.push_back("--jtag-port");
203	  vsim_pass.push_back(jtag_port);
204	  std::string err;
205	  const std::vector<std::string> vsim_argv =
206	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
207	  if (!err.empty()) {
208	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
209	    return 2;
210	  }
211	  std::fprintf(stderr,
212	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
213	               jtag_port.c_str());
214	  if (fork_background(vsim_argv) < 0) {
215	    std::fprintf(stderr,
216	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
217	    return 1;
218	  }
219	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
220	  // Wait for the port to be LISTENing before launching the debugger (it does not
221	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
222	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
223	  // but launch anyway if it never appears.
224	  if (const int pnum = std::atoi(jtag_port.c_str());
225	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
226	    std::fprintf(stderr,
227	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
228	                 "after 20s; launching the debugger anyway\n",
229	                 jtag_port.c_str());
230	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
231	  // localhost, port 9104) instead of its default real-hardware adapter; without
232	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
233	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
234	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
235	}
