237	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
238	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
239	// engine's own output. Unlike fast, this must discover the vsim build(s) to
240	// resolve the engine (explicit --engine, else the sole one).
241	int run_accurate(const Cli& cli) {
242	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
243	  // --describe subprocess per vsim build only to fail on the argument.
244	  if (int rc = check_one_elf(cli, "cycle")) return rc;
245	  // --mem-size is validated but has nothing to size: the cycle engine always
246	  // models its full DRAM window. Say so instead of silently ignoring it.
247	  if (!cli.mem_size.empty()) {
248	    std::string se;
249	    if (parse_size(cli.mem_size, se); !se.empty()) {
250	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
251	                   se.c_str());
252	      return 2;
253	    }
254	    std::fprintf(stderr,
255	                 "[andesim] --mem-size: the cycle engine models its full "
256	                 "DRAM window; nothing to size\n");
257	  }
258	  Discovery disc = discover_engines();
259	  std::string err;
260	  const EngineDescriptor* eng =
261	      resolve_accurate_engine(disc.engines, cli.engine, err);
262	  if (!eng) {
263	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
264	    // Surface why an expected engine may be absent (failed --describe, etc.).
265	    for (const std::string& w : disc.warnings)
266	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
267	    return 2;
268	  }
269	  // --dry-run previews the standalone command and spawns nothing, so it takes
270	  // precedence over the interactive --gdb path (a dry run launches no debugger).
271	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
272	  return run_standalone(cli, *eng, "cycle");
273	}
