275	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
276	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
277	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
278	// driver's tests/e2e.sh delegation with a single window-cycle line.
279	int run_hybrid(const Cli& cli) {
280	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
281	  auto fail = [](const std::string& msg) {
282	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
283	    return 2;
284	  };
285	
286	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
287	
288	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
289	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
290	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
291	  const std::string elf_path = abs_elf(cli.positional[0], "--mode hybrid");
292	  if (elf_path.empty()) return 2;
293	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
294	
295	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
296	  // mistake fails fast without spawning a --describe per Verilator build.
297	  std::string err;
298	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
299	  if (!err.empty()) return fail(err);
300	
301	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
302	  if (!err.empty()) return fail(err);
303	
304	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
305	  if (!cli.mem_size.empty()) {
306	    std::string se;
307	    mem = parse_size(cli.mem_size, se);
308	    if (!se.empty()) return fail("--mem-size: " + se);
309	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the mmap backend doubles
310	    // as guest RAM here. Failing now beats allocating a huge mmap file first and
311	    // letting QEMU die late.
312	    if (mem > 2LL * 1024 * 1024 * 1024)
313	      return fail("--mem-size " + cli.mem_size +
314	                  " exceeds the AE350 DRAM window (2G)");
315	  }
316	
317	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
318	  // or the sole cycle-accurate engine (reusing the F8 selector).
319	  Discovery disc = discover_engines();
320	  const EngineDescriptor* acc =
321	      resolve_accurate_engine(disc.engines, cli.engine, err);
322	  if (!acc) {
323	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
324	    for (const std::string& w : disc.warnings)
325	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
326	    return 2;
327	  }
328	
329	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
330	  // cannot share architectural state with the rv64 fast leg).
331	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
332	
333	  Plan plan;
334	  plan.elf = elf_path;
335	  plan.mem_size = mem;
336	  Step qemu_step{kQemuId, "fast-leg", trig};
337	  Step vsim_step{acc->id, "accurate-leg", trig};
338	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
339	  plan.steps = {qemu_step, vsim_step};
340	
341	  // Banner to stderr so the window-cycle result stands alone on stdout.
342	  // vlen is the synced value the fast leg inherits from the engine.
343	  std::fprintf(stderr,
344	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
345	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
346	               elf.stem().string().c_str());
347	
348	  PlanOptions opts;
349	  opts.dry_run = cli.dry_run;
350	  const PlanResult r = run_plan(plan, disc.engines, opts);
351	  if (!r.ok()) {
352	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
353	    return 1;
354	  }
355	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
356	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
357	  // then the vsim accurate leg -- and stop. Nothing was spawned.
358	  if (cli.dry_run) {
359	    std::vector<std::string> labels;
360	    labels.reserve(plan.steps.size());
361	    for (const Step& s : plan.steps)
362	      labels.push_back(s.role + " [" + s.engine_id + "]");
363	    return print_dry_run(r.argvs, labels);
364	  }
365	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
366	  // vsim mcycle delta.
367	  const unsigned long long q_mc = r.phases[0].mcycle;
368	  const unsigned long long v_mc = r.phases[1].mcycle;
369	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
370	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
371	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
372	              elf.stem().string().c_str());
373	  return 0;
374	}
