378	int cmd_run(const Cli& cli) {
379	  if (cli.model.empty()) {
380	    std::fprintf(stderr,
381	                 "andesim run: --mode fast|cycle|hybrid is required "
382	                 "(pick the composition; see 'andesim run --help')\n");
383	    return 2;
384	  }
385	  if (!find_model(cli.model)) {
386	    std::fprintf(stderr,
387	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
388	                 cli.model.c_str());
389	    return 2;
390	  }
391	  if (!cli.gdb_port.empty() && !cli.gdb) {
392	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
393	    return 2;
394	  }
395	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
396	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
397	  if (cli.gdb && cli.model == "hybrid") {
398	    std::fprintf(stderr,
399	                 "andesim run: --gdb is not supported with --mode hybrid\n");
400	    return 2;
401	  }
402	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
403	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
404	  // handoff builds itself, so there is no single "the engine" to forward to.
405	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
406	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
